SELECT v.*
FROM erp_finance_voucher v
WHERE v.deleted = 0

    AND v.ledger_id IN

        #{ledgerId}



    AND v.dept_id IN

        #{deptId}



    AND v.ledger_id = #{reqVO.ledgerId}


    AND v.period_id = #{reqVO.periodId}


    AND v.biz_type = #{reqVO.bizType}


    AND v.biz_no LIKE CONCAT('%', #{reqVO.bizNo}, '%')


    AND v.voucher_no LIKE CONCAT('%', #{reqVO.voucherNo}, '%')


    AND v.status = #{reqVO.status}


    AND v.voucher_time  >=  #{reqVO.voucherTime[0]}


    AND v.voucher_time  <=  #{reqVO.voucherTime[1]}


    AND (

        (v.ledger_id != #{ledgerId}
        OR NOT EXISTS (
            SELECT 1
            FROM erp_finance_voucher_entry e
            WHERE e.voucher_id = v.id
              AND e.deleted = 0
              AND e.subject_code NOT IN

                #{subjectCode}

        ))

    )

ORDER BY v.id DESC
